-- mod-subclass: copies of class and borrowable spells the other head casts with her left arm: spells use the left-arm cast animations and glow at the left hand, melee strikes swing the weapon her left hand holds, gun shots fly from her left hand without the ranged slot, and no copy puts the main hand's weapon away.

DROP TABLE IF EXISTS `mod_subclass_other_head_spell`;
CREATE TABLE `mod_subclass_other_head_spell` (
    `SpellId` INT UNSIGNED NOT NULL,
    `ShownId` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`SpellId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `mod_subclass_other_head_spell`;
